import{_ as e,o as t,c as l,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"2017Q3 Ceph社区季度进展报告","description":"","frontmatter":{"title":"2017Q3 Ceph社区季度进展报告","date":"2017-09-01T00:00:00.000Z","updated":"2017-09-01T00:00:00.000Z","tags":["Ceph","社区动态","季度报告"],"categories":["季度总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2017Q3_Ceph社区季度总结.md","filePath":"posts/2017/2017Q3_Ceph社区季度总结.md","lastUpdated":1780460162000}'),a={name:"posts/2017/2017Q3_Ceph社区季度总结.md"};function i(n,o,s,h,u,g){return t(),l("div",null,[...o[0]||(o[0]=[r('<h1 id="ceph-社区季度进展报告-—-2017-q3" tabindex="-1">Ceph 社区季度进展报告 — 2017 Q3 <a class="header-anchor" href="#ceph-社区季度进展报告-—-2017-q3" aria-label="Permalink to &quot;Ceph 社区季度进展报告 — 2017 Q3&quot;">​</a></h1><hr><h2 id="_1-本季度重点议题" tabindex="-1">1. 本季度重点议题 <a class="header-anchor" href="#_1-本季度重点议题" aria-label="Permalink to &quot;1. 本季度重点议题&quot;">​</a></h2><p>本季度两次开发者月度会议围绕以下方向持续讨论：</p><ul><li><strong>Luminous 版本发布冲刺</strong>：整个季度的核心工作是推动 Luminous 版本进入 GA 状态，bug 修复贯穿始终。</li><li><strong>数据复制与一致性</strong>：跨数据中心复制的全局顺序保证、OSD 故障时的复制正确性，是两次会议均涉及的核心难题。</li><li><strong>性能与 QoS</strong>：mClock 调度器优化、统一 QoS 策略、RBD 共享读取缓存等议题反复出现，体现了社区对 I/O 质量管控的持续投入。</li><li><strong>存储效率</strong>：数据去重（deduplication）和 PG 日志修剪（PG log trimming）作为降低存储开销的关键方向被重点讨论。</li></ul><hr><h2 id="_2-技术亮点" tabindex="-1">2. 技术亮点 <a class="header-anchor" href="#_2-技术亮点" aria-label="Permalink to &quot;2. 技术亮点&quot;">​</a></h2><h3 id="管理与可观测性" tabindex="-1">管理与可观测性 <a class="header-anchor" href="#管理与可观测性" aria-label="Permalink to &quot;管理与可观测性&quot;">​</a></h3><p>在 <a href="/VideoSummary/posts/2017/2017-AUG-02_-_-_Ceph_Developer_Monthly.html">2017-AUG-02 开发者月度会议</a>) 中，多项面向运维的新能力被集中介绍：</p><ul><li><strong>新 Web 仪表板</strong>：提供集群监控与管理的图形化界面，降低运维门槛。</li><li><strong>服务映射（Service Map）</strong>：支持从命令行或模块中查询集群内各服务的注册信息。</li><li><strong>应用程序标签（Application Tags）</strong>：允许对存储池打标签，便于区分业务用途。</li><li><strong>配置系统改进</strong>：新增 <code>help</code> 和 <code>diff</code> 子命令，提升配置可读性与变更追踪能力。</li><li><strong>Prometheus 集成</strong>：将 Ceph 指标暴露给 Prometheus，打通与主流监控生态的对接。</li><li><strong>平衡器模块（Balancer Module）</strong>：提供数据均衡操作的简化入口，支持自动调整 PG 分布。</li></ul><h3 id="数据路径与缓存" tabindex="-1">数据路径与缓存 <a class="header-anchor" href="#数据路径与缓存" aria-label="Permalink to &quot;数据路径与缓存&quot;">​</a></h3><ul><li><strong>共享 RBD 客户端缓存</strong>：在 <a href="/VideoSummary/posts/2017/2017-SEP-06_-_-_Ceph_Developer_Monthly.html">2017-SEP-06 开发者月度会议</a>) 中提出基于共享内存与 IPC 机制的缓存共享方案，目标是减少同主机多客户端场景下的重复 I/O。</li><li><strong>速率限制（Rate Limiting）</strong>：支持对特定账户限制 I/O 操作速率，为多租户场景提供基础隔离能力。</li><li><strong>快速失败请求（Fast Fail）</strong>：引入请求快速失败机制，减少异常路径下的等待延迟。</li></ul><h3 id="存储效率" tabindex="-1">存储效率 <a class="header-anchor" href="#存储效率" aria-label="Permalink to &quot;存储效率&quot;">​</a></h3><ul><li><strong>数据去重（Deduplication）</strong>：提出使用对象映射与内容地址存储池（content-addressed pool）实现块级去重，详见 <a href="/VideoSummary/posts/2017/2017-SEP-06_-_-_Ceph_Developer_Monthly.html">2017-SEP-06 开发者月度会议</a>)。</li><li><strong>统一 PG 日志修剪</strong>：提出基于时间戳与全局 LRU 的 PG log修剪策略，控制日志膨胀。</li><li><strong>快照删除优化</strong>：通过从 OSD map 中提前移除已删除快照信息，加速快照清理流程。</li></ul><h3 id="复制与一致性" tabindex="-1">复制与一致性 <a class="header-anchor" href="#复制与一致性" aria-label="Permalink to &quot;复制与一致性&quot;">​</a></h3><ul><li><strong>跨数据中心复制</strong>：提出时间切片（time slicing）与定时器机制来同步跨 DC 的客户端操作顺序，应对全局顺序维护的挑战。</li><li><strong>复制正确性保障</strong>：提出利用原始操作日志（raw operation log）与快照（snapshot）组合的方式，在 OSD 故障场景下保证对象状态正确性。</li></ul><h3 id="qos-与调度" tabindex="-1">QoS 与调度 <a class="header-anchor" href="#qos-与调度" aria-label="Permalink to &quot;QoS 与调度&quot;">​</a></h3><ul><li><strong>统一 QoS</strong>：讨论了基于 QoS 策略表的统一控制框架，目标是跨 RBD、CephFS、RGW 提供一致的 I/O 优先级管理。</li><li><strong>mClock 优化</strong>：提出通过分片（sharding）与线程池改进 mClock 调度器的吞吐与延迟表现。</li></ul><hr><h2 id="_3-重要决策与里程碑" tabindex="-1">3. 重要决策与里程碑 <a class="header-anchor" href="#_3-重要决策与里程碑" aria-label="Permalink to &quot;3. 重要决策与里程碑&quot;">​</a></h2><ul><li><strong>Luminous 版本即将 GA</strong>：在 <a href="/VideoSummary/posts/2017/2017-AUG-02_-_-_Ceph_Developer_Monthly.html">2017-AUG-02 开发者月度会议</a>) 中，Leo 明确表示 Luminous 处于最终 bug 修复阶段，这是本季度最重要的里程碑节点。Luminous 是 Ceph 首个正式包含 BlueStore 作为默认后端、并引入 MGR 框架的长期支持版本。</li><li><strong>MGR 模块生态初步成型</strong>：平衡器模块、状态模块、Prometheus 插件等均以 MGR 模块形式交付，标志着 MGR 插件化架构在本季度开始落地。</li><li><strong>跨集群复制方向确立</strong>：跨数据中心复制被列为后续重点开发方向，相关设计讨论已在本季度展开。</li></ul><hr><h2 id="_4-社区动态" tabindex="-1">4. 社区动态 <a class="header-anchor" href="#_4-社区动态" aria-label="Permalink to &quot;4. 社区动态&quot;">​</a></h2><ul><li><strong>开发者月度会议（CDM）持续举行</strong>：本季度记录了 8 月和 9 月两次 Ceph Developer Monthly 会议，参与者涵盖核心开发者与社区贡献者，议题覆盖从版本发布到前沿特性设计的完整范围。</li><li><strong>Kubernetes 集成关注度上升</strong>：在 <a href="./2017-AUG-02_-_Ceph_Developer_Monthly.html">2017-AUG-02 开发者月度会议</a> 中提及 Ceph 与 Kubernetes 的集成，反映出社区对云原生场景的关注开始增强。</li><li><strong>本季度暂无相关记录</strong>：本季度材料中未出现具体的 Cephalocon 或线下 Summit 活动记录，亦无新贡献者统计数据。</li></ul><hr><h2 id="_5-下季度展望" tabindex="-1">5. 下季度展望 <a class="header-anchor" href="#_5-下季度展望" aria-label="Permalink to &quot;5. 下季度展望&quot;">​</a></h2><p>基于本季度讨论内容，预计 2017 Q4 将重点推进以下方向：</p><ol><li><strong>Luminous 正式发布后的稳定化工作</strong>：GA 后的 bug 修复、文档完善与用户反馈处理将是近期主线。</li><li><strong>跨数据中心复制落地</strong>：本季度完成了设计讨论，下季度有望进入原型实现阶段。</li><li><strong>去重功能推进</strong>：内容地址存储池方案已有初步设计，预计进入编码阶段。</li><li><strong>mClock 与统一 QoS 集成</strong>：两者均处于设计收敛阶段，下季度可能合并为统一的 I/O 调度框架推进。</li><li><strong>MGR 模块持续扩展</strong>：随着 Luminous 发布，社区贡献者有望围绕 MGR 框架开发更多监控、管理类插件。</li><li><strong>云原生方向深化</strong>：Kubernetes 与 Prometheus 集成已在本季度提及，预计下季度会有更具体的 CSI 或 Rook 相关讨论出现。</li></ol><hr><h2 id="参考文章" tabindex="-1">参考文章 <a class="header-anchor" href="#参考文章" aria-label="Permalink to &quot;参考文章&quot;">​</a></h2><ul><li><a href="/VideoSummary/posts/2017/2017-AUG-02_-_-_Ceph_Developer_Monthly.html">2017-AUG-02 :: Ceph Developer Monthly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-SEP-06_-_-_Ceph_Developer_Monthly.html">2017-SEP-06 :: Ceph Developer Monthly</a>)</li></ul>',31)])])}const d=e(a,[["render",i]]);export{p as __pageData,d as default};
